            //
            aScatter = (RotL64(aCarry, 5U) + RotL64(aPrevious, 26U)) ^ (RotL64(aIngress, 43U) ^ RotL64(aCross, 57U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterJ = (((aWandererC + RotL64(aScatter, 37U)) + RotL64(aCarry, 3U)) + 0xE53D159F3C59470AULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterK = ((aWandererD + RotL64(aPrevious, 29U)) + RotL64(aCarry, 19U)) + 0x54C560BCCEC0E3F8ULL;
            aOrbiterH = (aWandererK + RotL64(aCross, 60U)) + 0x25302978936F5627ULL;
            aOrbiterB = (aWandererF + RotL64(aIngress, 51U)) + 0x1B81030E6365F98DULL;
            aOrbiterI = ((aWandererJ + RotL64(aCross, 19U)) + 0x9E9450C7AEF27466ULL) + aTwistOrbiterAssignSaltD[((aIndex + 29U)) & S_SALT1];
            aOrbiterE = ((aWandererE + RotL64(aIngress, 3U)) + RotL64(aCarry, 41U)) + 0x53DED23589F607E5ULL;
            aOrbiterA = (aWandererI + RotL64(aPrevious, 13U)) + 0x7E560986C43B8C1EULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0x684A7863145968FCULL;
