            aOrbiterA = RotL64((aOrbiterA * 0xB1D38CA09F8DDE7BULL), 41U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0x68FC7D9E9CF83184ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x74FA4698F31394CCULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x6B635CBCCC1FA14BULL), 47U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0xC72AE419873928BCULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0x18E2862B64591A72ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x493047CDD336A9C5ULL), 3U);
            //
            aIngress = RotL64(aOrbiterH, 27U) ^ aOrbiterA;
