            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterE, 21U));
            aIngress = aIngress + RotL64(aOrbiterJ, 41U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererE = aWandererE + ((RotL64(aScatter, 21U) + aOrbiterK) + RotL64(aOrbiterE, 39U));
            aWandererC = aWandererC ^ ((RotL64(aCross, 39U) + aOrbiterH) + RotL64(aOrbiterE, 3U));
            aWandererJ = aWandererJ + (((RotL64(aPrevious, 14U) + aOrbiterH) + RotL64(aOrbiterI, 20U)) + RotL64(aCarry, 51U));
