            aWandererD = aWandererD + ((((RotL64(aCross, 57U) + RotL64(aOrbiterA, 53U)) + aOrbiterI) + RotL64(aCarry, 35U)) + aTwistWandererUpdateSaltF[(((31U - aIndex) + 6U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aIngress, 47U) + aOrbiterE) + RotL64(aOrbiterB, 29U));
            aWandererI = aWandererI + ((RotL64(aScatter, 5U) + aOrbiterJ) + RotL64(aOrbiterB, 47U));
