            //
            aOrbiterE = (aWandererG + RotL64(aScatter, 29U)) + 0x3DB3F0D03202D884ULL;
            aOrbiterG = ((aWandererE + RotL64(aPrevious, 19U)) + RotL64(aCarry, 57U)) + 0x68359C3168840F12ULL;
            aOrbiterC = (aWandererA + RotL64(aIngress, 52U)) + 0x66C9AF2F7A9C3954ULL;
            aOrbiterF = ((aWandererF + RotL64(aCross, 41U)) + RotL64(aCarry, 41U)) + 0x822E7CEFE184A283ULL;
            aOrbiterA = (((aWandererJ + RotL64(aScatter, 11U)) + RotL64(aCarry, 23U)) + 0xAC5B434221636CD2ULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterB = (aWandererI + RotL64(aPrevious, 35U)) + 0x21090EB5273A9669ULL;
            aOrbiterK = ((aWandererB + RotL64(aIngress, 5U)) + 0x9093D4C6C410D5C4ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 29U)) & S_SALT1];
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0xEEB8964B183C5A42ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterE) ^ 0xD65D7033BF05047EULL;
            aOrbiterC = RotL64((aOrbiterC * 0xBD31EAC80A1E8AE9ULL), 5U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0xE21E1461CDD03E4CULL) + aTwistOrbiterUpdateSaltC[((aIndex + 18U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterF) ^ 0x4C2D58970EFD7390ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xF29C781A149E97B9ULL), 41U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterE) + 0x79D22DE055D1A7BDULL) + aTwistOrbiterUpdateSaltF[((aIndex + 21U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0x7457C9D5A31A76ACULL;
            aOrbiterB = RotL64((aOrbiterB * 0x3C23CC1F1392C531ULL), 47U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterF) + 0x2B906745AB1B9B99ULL) + aTwistOrbiterUpdateSaltE[((aIndex + 19U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0xC6A8F714A4F960D5ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xF86DD44D0FC1BA23ULL), 11U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xFEF8BBE6BA6BC5B4ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0x3763BDB4596074BCULL;
            aOrbiterA = RotL64((aOrbiterA * 0xF71B4B097C058AF5ULL), 57U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0xF6DB8A88FA302464ULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0xA409C4E3639F6C8FULL;
            aOrbiterK = RotL64((aOrbiterK * 0x9D1EBD59BDCC1759ULL), 27U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x718AEFCC762B7CF7ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0x9BD28F2911E58F26ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xD073379BAA78DB0FULL), 35U);
            //
            aIngress = RotL64(aOrbiterK, 29U) ^ aOrbiterE;
            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterG, 5U));
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterF, 47U));
