            //
            aWandererA = aWandererA ^ (((RotL64(aPrevious, 47U) + RotL64(aOrbiterF, 35U)) + aOrbiterG) + aTwistWandererUpdateSaltD[((aIndex + 15U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aScatter, 19U) + RotL64(aOrbiterA, 12U)) + aOrbiterC) + RotL64(aCarry, 47U));
            aWandererI = aWandererI ^ ((RotL64(aIngress, 29U) + RotL64(aOrbiterC, 57U)) + aOrbiterK);
