            aOrbiterC = (aOrbiterC + aOrbiterA) + 0x07ECE0AC2B97BE1AULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0xEA882C58FE6286BDULL;
            aOrbiterD = RotL64((aOrbiterD * 0x27417021729FC877ULL), 57U);
