            aOrbiterK = (aOrbiterK + aOrbiterD) + 0xED6759085EF5FB77ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterK) ^ 0x7889CAF984A7099BULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 29U)) & S_SALT1];
