            aWandererA = aWandererA + ((((RotL64(aCross, 11U) + RotL64(aOrbiterI, 21U)) + aOrbiterA) + RotL64(aCarry, 29U)) + aTwistWandererUpdateSaltA[((aIndex + 25U)) & S_SALT1]);
