            //
            aOrbiterF = (aWandererC + RotL64(aCross, 47U)) + 0x336529E42BC0486EULL;
            aOrbiterE = ((aWandererF + RotL64(aPrevious, 26U)) + 0xD39DB7358159DBB3ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterJ = ((aWandererB + RotL64(aScatter, 35U)) + RotL64(aCarry, 5U)) + 0x3A4172EB0BA27823ULL;
            aOrbiterH = ((aWandererG + RotL64(aIngress, 3U)) + 0xC2512089183C3A7CULL) + aTwistOrbiterAssignSaltD[((aIndex + 29U)) & S_SALT1];
            aOrbiterI = (aWandererJ + RotL64(aScatter, 11U)) + 0x0D3C1A0ED8FAF696ULL;
            aOrbiterB = ((aWandererI + RotL64(aPrevious, 41U)) + RotL64(aCarry, 29U)) + 0x556BC454D2712C6DULL;
            aOrbiterD = ((aWandererA + RotL64(aCross, 19U)) + RotL64(aCarry, 41U)) + 0x1650EE3AD830AD3FULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x8DB4CBACFCCFD6C1ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x4AAAD2793A936391ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x264D04C67B1187B3ULL), 51U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x8147BBACEDBF16CFULL;
