            aOrbiterB = ((aOrbiterB + aOrbiterI) + 0xE5F5C9DA47ED9B30ULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0x41BDB51EC826BACFULL;
            aOrbiterE = RotL64((aOrbiterE * 0xF6FEA9E37A4CF9D7ULL), 57U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0x63A49D88525339D7ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterE) ^ 0xD135A43DD43CA7D7ULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x6399EE442B76DF6FULL), 19U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0x6AD8BB3505BE2036ULL;
