            aOrbiterG = (aWandererA + RotL64(aIngress, 21U)) + 0x2CF7F6610FDDE12EULL;
            aOrbiterE = (aWandererG + RotL64(aScatter, 48U)) + 0xCBC0F5AC60EF5D6FULL;
