            aOrbiterG = RotL64((aOrbiterG * 0x6567D111E0942417ULL), 53U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x337C93145F22D8F6ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0xBBEE81524F461D57ULL;
