            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterI) + 0xE7066416A72F6129ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 10U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0xF6A8F14A36CB295CULL;
            aOrbiterD = RotL64((aOrbiterD * 0xAF2E2A6EA9D8A991ULL), 3U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterJ) + 0x0A20E77E6949FD58ULL) + aTwistOrbiterUpdateSaltE[((aIndex + 29U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterK) ^ 0x159889A689FD227CULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xB33821366B65DD25ULL), 47U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterK) + 0x216A38DFAB8626D5ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 19U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0x1E18B2B01392C789ULL;
