            //
            aWandererD = aWandererD + (((RotL64(aCross, 57U) + RotL64(aOrbiterJ, 43U)) + aOrbiterK) + RotL64(aCarry, 39U));
            aWandererF = aWandererF ^ ((RotL64(aScatter, 13U) + aOrbiterF) + RotL64(aOrbiterI, 4U));
