            aWandererC = aWandererC ^ (((RotL64(aPrevious, 35U) + aOrbiterF) + RotL64(aOrbiterH, 51U)) + aTwistWandererUpdateSaltC[((aIndex + 14U)) & S_SALT1]);
            aWandererE = aWandererE + ((RotL64(aCross, 43U) + RotL64(aOrbiterH, 19U)) + aOrbiterG);
            aWandererI = aWandererI ^ (((RotL64(aScatter, 27U) + RotL64(aOrbiterK, 57U)) + aOrbiterD) + aTwistWandererUpdateSaltF[((aIndex + 25U)) & S_SALT1]);
