            aOrbiterC = (aWandererF + RotL64(aPrevious, 19U)) + 0x4ED03DB6A2D12CECULL;
            aOrbiterG = ((aWandererC + RotL64(aCross, 57U)) + RotL64(aCarry, 19U)) + 0xED3E8FBCEE075A74ULL;
