            aOrbiterK = (aWandererK + RotL64(aScatter, 13U)) + 0x1613A04AFA9F1312ULL;
            aOrbiterD = (((aWandererA + RotL64(aPrevious, 35U)) + RotL64(aCarry, 37U)) + 0x3B94F29E2B7B9432ULL) + aTwistOrbiterAssignSaltF[((aIndex + 7U)) & S_SALT1];
