            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0x8A6445121B05C636ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 4U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x947481B0820D513BULL), 5U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x65BC5E4F7A49087AULL;
