            aOrbiterJ = RotL64((aOrbiterJ * 0xE37EFCCE63207CF9ULL), 19U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0x6A9BB73435DB7BD8ULL;
