            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0x9084668E4548D5CAULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterJ) ^ 0x50404DDDE91D60C0ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xD9B4D4AB64323411ULL), 35U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x7F4D556480CEC893ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterD) ^ 0x71DD53EAFB5F2A20ULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 17U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xC05906382BC1BF99ULL), 29U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x37EF62C705E6E899ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterK) ^ 0x07F3682ACE1020CEULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 11U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x53365DB88303EA7BULL), 41U);
