            aWandererD = aWandererD ^ (((RotL64(aCross, 53U) + RotL64(aOrbiterK, 51U)) + aOrbiterB) + aTwistWandererUpdateSaltD[(((31U - aIndex) + 3U)) & S_SALT1]);
