            aOrbiterC = (aWandererG + RotL64(aScatter, 18U)) + 0x43F3CA85A6D3D314ULL;
            aOrbiterE = (aWandererE + RotL64(aCross, 35U)) + 0x10879FCA458B8B37ULL;
            aOrbiterB = (aWandererF + RotL64(aPrevious, 57U)) + 0xB640CEBAE378A562ULL;
            aOrbiterF = ((aWandererI + RotL64(aScatter, 43U)) + RotL64(aCarry, 23U)) + 0x7C72B2FBD25DDEC6ULL;
            aOrbiterJ = ((aWandererB + RotL64(aIngress, 53U)) + RotL64(aCarry, 37U)) + 0xAF9D03E5650A2AF4ULL;
            aOrbiterA = ((aWandererH + RotL64(aCross, 47U)) + 0x8FAD68CB6566A978ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterG = ((aWandererK + RotL64(aPrevious, 3U)) + RotL64(aCarry, 57U)) + 0x37C60FD0A0598083ULL;
            aOrbiterI = ((aWandererA + RotL64(aIngress, 10U)) + 0x3DF161A6F48EBA46ULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 17U)) & S_SALT1];
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0xE8857440EECCE62DULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0xAE5A385C63D583EEULL;
            aOrbiterE = RotL64((aOrbiterE * 0x8A5434DD67817DA5ULL), 3U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0x3BDC18E845FC359EULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterC) ^ 0xCF1F3E46A1C0C8C7ULL;
