            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0xD8AD0A3066BF64E6ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0xCBAB1B65CD8A7B2EULL;
