            aWandererK = aWandererK ^ (((RotL64(aIngress, 35U) + RotL64(aOrbiterF, 50U)) + aOrbiterH) + aTwistWandererUpdateSaltA[((aIndex + 25U)) & S_SALT1]);
            aWandererI = aWandererI + ((RotL64(aScatter, 60U) + aOrbiterA) + RotL64(aOrbiterH, 19U));
