            aOrbiterE = (((aWandererB + RotL64(aCross, 27U)) + RotL64(aCarry, 29U)) + 0x4CCE7B8479DF4628ULL) + aKeyRotateOrbiterAssignSaltC[((aIndex + 29U)) & S_SALT1];
