            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aCarry, 18U) ^ RotL64(aPrevious, 5U)) + (RotL64(aCross, 57U) ^ RotL64(aIngress, 41U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterB = (aWandererH + RotL64(aScatter, 11U)) + 0x8C29DE3C8931A4E1ULL;
            aOrbiterI = ((aWandererA + RotL64(aPrevious, 28U)) + 0x5DD1D3D9C89B603EULL) + aKeyRotateOrbiterAssignSaltF[((aIndex + 4U)) & S_SALT1];
            aOrbiterA = ((aWandererK + RotL64(aIngress, 57U)) + RotL64(aCarry, 3U)) + 0x82646BB9A941A980ULL;
            aOrbiterJ = (aWandererE + RotL64(aCross, 5U)) + 0x39D607D86B6321DDULL;
            aOrbiterC = (((aWandererD + RotL64(aPrevious, 21U)) + RotL64(aCarry, 29U)) + 0x5EA025543AC340B8ULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterF = (aWandererB + RotL64(aCross, 37U)) + 0xEF4365DB2A6E99AAULL;
            aOrbiterD = ((aWandererC + RotL64(aScatter, 51U)) + RotL64(aCarry, 53U)) + 0x727A5182C9E86B32ULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0x717AE4AA082FC733ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0x14D93412C9DA7468ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xEFB6EE97958938DDULL), 47U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x97528C7C55F87EAFULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0x20DCDB89B8DFAE66ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x86F9BB578CB2E467ULL), 29U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0xE84E25F2B4998DBBULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x47D861C8D2FA1832ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x7A541C7AB231BF29ULL), 53U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterF) + 0xDA05186B936D4148ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0xE13EA3EB3A6EECF9ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xA142C1D6ADBC7EF5ULL), 13U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterJ) + 0x1ACCE80B9D9BD163ULL) + aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterI) ^ 0x60225E6328355C65ULL) ^ aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x457F2CE0CD9BD1AFULL), 35U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0x6E9F13D4814FC3A6ULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 20U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterD) ^ 0xE481B37EE96FBCF1ULL) ^ aKeyRotateOrbiterUpdateSaltE[((aIndex + 19U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xD3CADB0497AB8F2BULL), 19U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0x4FC15E3CE7F779E9ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0xAE77A1049E8BA390ULL;
