            aWandererD = aWandererD ^ ((RotL64(aIngress, 23U) + RotL64(aOrbiterF, 14U)) + aOrbiterJ);
            aWandererK = aWandererK + ((((RotL64(aScatter, 29U) + aOrbiterJ) + RotL64(aOrbiterD, 3U)) + RotL64(aCarry, 3U)) + aKeyRotateWandererUpdateSaltD[(((31U - aIndex) + 11U)) & S_SALT1]);
            aWandererA = aWandererA ^ ((RotL64(aCross, 12U) + aOrbiterB) + RotL64(aOrbiterF, 47U));
            aWandererC = aWandererC + (((RotL64(aPrevious, 35U) + RotL64(aOrbiterB, 41U)) + aOrbiterD) + RotL64(aCarry, 43U));
            aWandererE = aWandererE ^ ((RotL64(aIngress, 41U) + RotL64(aOrbiterC, 53U)) + aOrbiterI);
            aWandererB = aWandererB + (((RotL64(aScatter, 5U) + RotL64(aOrbiterA, 27U)) + aOrbiterJ) + aKeyRotateWandererUpdateSaltF[((aIndex + 5U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 57U) + RotL64(aOrbiterI, 21U)) + aOrbiterJ);
