            //
            aWandererI = aWandererI + ((RotL64(aPrevious, 34U) + aOrbiterH) + RotL64(aOrbiterA, 3U));
            aWandererB = aWandererB ^ ((RotL64(aScatter, 53U) + RotL64(aOrbiterJ, 5U)) + aOrbiterD);
            aWandererA = aWandererA + (((RotL64(aIngress, 21U) + aOrbiterA) + RotL64(aOrbiterK, 46U)) + RotL64(aCarry, 43U));
            aWandererD = aWandererD ^ ((RotL64(aCross, 5U) + RotL64(aOrbiterC, 13U)) + aOrbiterK);
