            aWandererH = aWandererH ^ ((RotL64(aScatter, 57U) + aOrbiterF) + RotL64(aOrbiterE, 23U));
            aWandererG = aWandererG + ((((RotL64(aPrevious, 11U) + RotL64(aOrbiterG, 37U)) + aOrbiterE) + RotL64(aCarry, 29U)) + aKeyRotateWandererUpdateSaltD[((aIndex + 3U)) & S_SALT1]);
            aWandererF = aWandererF ^ ((RotL64(aIngress, 23U) + aOrbiterB) + RotL64(aOrbiterI, 21U));
            aWandererC = aWandererC + ((RotL64(aCross, 41U) + RotL64(aOrbiterJ, 43U)) + aOrbiterG);
            //
