            aScatter = (RotL64(aIngress, 40U) ^ RotL64(aCarry, 27U)) ^ (RotL64(aCross, 11U) + RotL64(aPrevious, 53U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterJ = ((aWandererF + RotL64(aCross, 23U)) + 0xF8E29463172A5A4DULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterB = (aWandererI + RotL64(aPrevious, 43U)) + 0x02AFE9070BC19562ULL;
