            aOrbiterK = (((aWandererJ + RotL64(aPrevious, 27U)) + RotL64(aCarry, 23U)) + 0xAF0BBF6BF9383278ULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 9U)) & S_SALT1];
            aOrbiterA = ((aWandererK + RotL64(aIngress, 3U)) + RotL64(aCarry, 11U)) + 0xF8DF78E6456646D2ULL;
            aOrbiterC = ((aWandererD + RotL64(aScatter, 53U)) + RotL64(aCarry, 27U)) + 0x170CC2BC50699072ULL;
