            aOrbiterK = (aOrbiterK + aOrbiterA) + 0x2A8303D70D897158ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0xB4DA92F34C7A8DE9ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x26633C2421AD3A69ULL), 37U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xE9D4EEEA1B1248BDULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterC) ^ 0x0F9B5E3E30270C2FULL) ^ aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xE7202A4EDABDDDA7ULL), 35U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterC) + 0xAF0A6EB9A5FB96ACULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0x299A8E3C96CB0573ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x98408B97E89DB261ULL), 5U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x0C6C3D53A076F5D7ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0x7B120B9415B6ABE5ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x7AC8306B69BD6269ULL), 47U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterD) + 0xAE2626E86118BAB1ULL) + aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x08CDE122C120F1E6ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x872B8F0439120B8DULL), 29U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0x428A2E675329CB18ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterD) ^ 0x5D11CA4D1D4388E7ULL) ^ aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x8A59DDEF7EAD62C7ULL), 13U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x27E35FC869A1469CULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x29A7607482D2C57DULL;
            aOrbiterD = RotL64((aOrbiterD * 0x46D2E86B2A868181ULL), 21U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0xF60C72C9968FAB2BULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x82730B989AFD0689ULL;
