            aOrbiterE = ((aOrbiterE + aOrbiterC) + 0x0AD1A46454DA298EULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 16U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterE) ^ 0x86189C2655A96354ULL) ^ aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xCFAF4F138383A099ULL), 21U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0x2195E225991DF79BULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterD) ^ 0x292ACF73A780F8B9ULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 17U)) & S_SALT1];
