            aWandererF = aWandererF + ((RotL64(aIngress, 29U) + aOrbiterJ) + RotL64(aOrbiterA, 29U));
            aWandererK = aWandererK ^ (((RotL64(aScatter, 19U) + aOrbiterJ) + RotL64(aOrbiterD, 3U)) + aKeyRotateWandererUpdateSaltB[(((31U - aIndex) + 27U)) & S_SALT1]);
