            aOrbiterK = (aWandererD + RotL64(aScatter, 19U)) + 0x37825C7568109C48ULL;
            aOrbiterD = (((aWandererG + RotL64(aIngress, 43U)) + RotL64(aCarry, 35U)) + 0xDB9334F698912AD1ULL) + aKeySpawnOrbiterAssignSaltC[((aIndex + 13U)) & S_SALT1];
            aOrbiterE = ((aWandererJ + RotL64(aScatter, 14U)) + 0x5966AC7BE3C56DE0ULL) + aKeySpawnOrbiterAssignSaltF[(((31U - aIndex) + 6U)) & S_SALT1];
