            aOrbiterH = (aOrbiterH + aOrbiterB) + 0x796637D7CCF5E67DULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterH) ^ 0xB6E96B3357BADC1DULL) ^ aKeySpawnOrbiterUpdateSaltD[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xA761F9C4EBD01CC7ULL), 43U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterA) + 0x7A98ABB0DB0CA8C9ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x7394175C3ABEE37AULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x30B265F8F94C9A93ULL), 23U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0x72910825A5026ED6ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterA) ^ 0xDBFB6BCAB6827493ULL) ^ aKeySpawnOrbiterUpdateSaltF[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xE660B97263CA91E9ULL), 19U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x5574D98CA10A6D23ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0x069D918DA23830A6ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x8A6B7D896F28F3B5ULL), 57U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0xFD8C6D32DD88DD8EULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterK) ^ 0x3C107293F962428BULL) ^ aKeySpawnOrbiterUpdateSaltB[(((31U - aIndex) + 19U)) & S_SALT1];
