            aOrbiterK = (aOrbiterK ^ aOrbiterD) ^ 0x41D6D81EA3EA7CEEULL;
            aOrbiterK = RotL64((aOrbiterK * 0x90F035CD5F190E67ULL), 47U);
            //
            aIngress = aOrbiterD ^ RotL64(aOrbiterC, 43U);
            aIngress = aIngress + (RotL64(aOrbiterF, 11U) ^ aOrbiterJ);
            aIngress = aIngress + (RotL64(aOrbiterA, 37U) ^ aOrbiterE);
            aIngress = aIngress + (RotL64(aOrbiterB, 28U) ^ aOrbiterK);
            aIngress = aIngress + RotL64(aOrbiterH, 53U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererK = aWandererK ^ ((RotL64(aCross, 39U) + RotL64(aOrbiterF, 13U)) + aOrbiterJ);
            aWandererC = aWandererC + (((RotL64(aPrevious, 4U) + aOrbiterF) + RotL64(aOrbiterA, 18U)) + aKeySpawnWandererUpdateSaltE[(((31U - aIndex) + 18U)) & S_SALT1]);
