            aIngress ^= (RotL64(aMagmaLaneB[((aIndex + 15709U)) & S_BLOCK1], 19U) ^ RotL64(aSpiritLaneB[((S_BLOCK1 - aIndex + 10966U)) & S_BLOCK1], 29U));
