            aCross ^= (RotL64(aKineticLaneC[((S_BLOCK1 - aIndex + 13003U)) & S_BLOCK1], 13U) ^ RotL64(aAetherLaneB[((aIndex + 15902U)) & S_BLOCK1], 57U));
